question:
The interviewer pastes this Node.js snippet:

```js
function getSentence(db, req) {
  const id = req.params.id;
  return db.query("SELECT text FROM sentences WHERE id = " + id);
}
```

What is the main security risk, and how would you fix it?

Full Block 1 drill — answer all four standard questions (1. explain in plain English then technically, 2. errors/bad practices, 3. how would you refactor, 4. security/maintainability risks) for:

```js
var mysql = require('mysql');
var con = mysql.createConnection({
  host: 'localhost', user: 'root',
  password: 'root123', database: 'app'
});

function reverse(id) {
  con.query("SELECT text FROM sentences WHERE id = " + id, function (err, rows) {
    var s = rows[0].text;
    var w = s.split(' ');
    for (var i = 0; i < w.length / 2; i++) {
      var tmp = w[i];
      w[i] = w[w.length - 1 - i];
      w[w.length - 1 - i] = tmp;
    }
    console.log(w.join(' '));
  });
}
```

